function seedArchive(){
 let stored;try{stored=JSON.parse(localStorage.getItem('marketplay-daily-archive')||'null')}catch(e){stored=null}
 if(!stored){stored={started:'2026-08-01',days:{}};for(let day=1;day<=20;day++){stored.days[day]={stories:[{title:archiveStories[day-1],story:(day-1)%stories.length},{title:archiveStories[Math.max(0,day-2)],story:(day+2)%stories.length}],simulations:[{title:simTitles[(day-1)%simTitles.length]}]};if(day%3===0)stored.days[day].simulations.push({title:simTitles[(day+2)%simTitles.length]})}stored.days[20]={stories:stories.map((s,i)=>({title:s.headline,story:i})),simulations:[{title:'Invest through a sudden rate shock'},{title:'Run a business while rates stay high'}]};try{localStorage.setItem('marketplay-daily-archive',JSON.stringify(stored))}catch(e){}}
 return stored;
}
