function showScreen(id){$$('.screen').forEach(x=>x.classList.remove('active'));$('#'+id).classList.add('active');window.scrollTo(0,0)}
function showMain(tab='today'){showScreen('main-screen');switchTab(tab)}
function switchTab(tab){$$('.tab-view').forEach(v=>v.classList.toggle('active',v.id===tab+'-view'));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===tab));window.scrollTo(0,0)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1900)}
function renderFeed(){
 $('#story-feed').innerHTML=stories.map((s,i)=>`<article class="news-card" data-story="${i}"><div class="hero ${s.art}"></div><div class="card-top"><span class="tag">${s.tag}</span><span class="impact">◆ ${s.impact}</span></div><div class="card-content"><div class="asset-row">${s.assets.map(a=>`<span class="asset-pill">${a[0]} <b class="${a[2]}">${a[1]}</b></span>`).join('')}</div><h2>${s.headline}</h2><p class="summary">${s.summary}</p><div class="meta"><span>${s.sources}</span><i class="source-dot"></i><span>${s.time}</span><i class="source-dot"></i><span>◷ ${s.mins}</span></div><div class="card-actions"><button class="explore-btn" data-open-story="${i}">Explore story →</button><button class="action-btn ${state.saved.has(i)?'saved':''}" data-save="${i}" aria-label="Save">${state.saved.has(i)?'▰':'▱'}</button><button class="action-btn" data-hide="${i}" aria-label="Not interested">•••</button></div><div class="scroll-hint">SWIPE FOR NEXT STORY ↓</div></div></article>`).join('');
}
function renderSaved(){const c=$('#saved-content');if(!state.saved.size){c.innerHTML=`<div class="empty-state"><div class="empty-icon">▱</div><h3>Build your learning library</h3><p>Save stories to revisit the explanation, activity or sources later.</p><button class="btn primary" data-nav="today">Find a story</button></div>`;return}c.innerHTML=`<div class="saved-list">${[...state.saved].map(i=>{const s=stories[i];return `<div class="saved-item"><div class="saved-thumb ${s.art}"></div><div><b>${s.headline}</b><small>${s.tag} · ${s.mins}</small></div><button class="text-btn" data-save="${i}">×</button></div>`}).join('')}</div>`}
function renderCalendar(){
 const cells=[];for(let i=0;i<5;i++)cells.push('<span class="calendar-day empty"></span>');
 for(let day=1;day<=31;day++){const future=day>20;cells.push(`<button class="calendar-day ${future?'future':'has-data'} ${day===state.calendarDay?'selected':''}" data-calendar-day="${day}">${day}</button>`)}
 $('#calendar-grid').innerHTML=cells.join('');renderArchiveDay();
}
function renderArchiveDay(){
 const day=state.calendarDay,data=dailyArchive.days[day]||{stories:[],simulations:[]};
 const date=new Date(2026,7,day);$('#archive-date-label').textContent=date.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();
 $('#archive-count').textContent=`${data.stories.length} ${data.stories.length===1?'story':'stories'} · ${data.simulations.length} ${data.simulations.length===1?'simulation':'simulations'}`;
 const storyItems=data.stories.map((item,i)=>`<button class="archive-item" data-archive-story="${item.story}"><div class="archive-thumb ${stories[item.story].art}"></div><div><span>STORY · ${stories[item.story].mins}</span><b>${item.title}</b><small>${stories[item.story].sources}</small></div><i>›</i></button>`);
 const simItems=data.simulations.map((item,i)=>`<button class="archive-item" data-investment="${i}"><div class="archive-thumb sim"></div><div><span>INVESTMENT SIM · 2 DECISIONS</span><b>${item.title}</b><small>About 2 minutes · Virtual money</small></div><i>›</i></button>`);
 let items=state.archiveFilter==='Stories'?storyItems:state.archiveFilter==='Simulations'?simItems:[...storyItems,...simItems];
 $('#archive-results').innerHTML=items.length?items.join(''):'<div class="archive-empty">Nothing stored for this filter.</div>';
 $('.filter-pill').textContent=`${state.archiveFilter} ▾`;
}
