 if(selectedEvent){$('#picker-story-title').textContent=selectedEvent.headline;$('#picker-story-source').textContent=`${selectedEvent.source} · Explore this event in two different ways`}
 $('#trade-level-tag').textContent=advanced?'Advanced market context':intermediate?'Guided order controls':'Extra guidance included';
