function renderTrading(){
 const c=$('#trading-content'),label=$('#trade-step-label'),screen=$('#trading-screen');if(screen)screen.scrollTop=0;$('#trade-cash').textContent=state.tradeRound?`£${(10000-state.tradeSize*10).toLocaleString()}`:'£10,000';
 const advanced=state.level==='Advanced';
 if(state.tradeRound===0){label.textContent='ROUND 1 OF 2';c.innerHTML=`<div class="trading-body"><div class="quote-head"><div><span>MPX</span><h2>£152.46</h2><small class="up">+£1.86 · +1.24% today</small></div><div class="market-open">MARKET OPEN</div></div>${tradingChart()}<button class="news-context" data-action="trade-marker"><span>12:00</span><div><b>Central bank holds rates at 5.25%</b><small>Tap to see why the price moved</small></div><i>›</i></button><div class="terminal-metrics"><div><span>DAY RANGE</span><b>146.80–153.02</b></div><div><span>VOLUME</span><b>18.4m</b></div>${advanced?'<div><span>P/E RATIO</span><b>21.8×</b></div><div><span>VOLATILITY</span><b>High</b></div>':'<div><span>RISK</span><b>High</b></div>'}</div><div class="order-ticket"><div class="ticket-head"><div><b>Your simulated order</b><small>${advanced?'Position sizing and risk controls':'Simple controls, with explanations'}</small></div><span>Virtual</span></div><div class="trade-actions"><button class="${state.tradeAction==='Buy'?'selected':''}" data-trade-action="Buy">Buy</button><button class="${state.tradeAction==='Short'?'selected':''}" data-trade-action="Short">Sell / short</button><button class="${state.tradeAction==='Watch'?'selected':''}" data-trade-action="Watch">Watch</button></div><label class="ticket-label">POSITION SIZE <button data-action="size-help">What’s this?</button></label><div class="size-options">${[5,10,20,30].map(n=>`<button class="${state.tradeSize===n?'selected':''}" data-trade-size="${n}">${n}%<small>£${n*100}</small></button>`).join('')}</div>${advanced?'<div class="risk-row"><label>Risk limit</label><select aria-label="Risk limit"><option>Exit if down 5%</option><option>Exit if down 8%</option><option>No automatic limit</option></select></div>':'<p class="guided-note">Your time horizon is five years. A larger position creates a larger potential gain—and a larger potential loss.</p>'}<button class="btn primary wide" data-action="execute-trade">${state.tradeAction==='Watch'?'Continue without trading':'Place simulated order'} →</button></div><p class="terminal-disclaimer">Simplified educational simulation. No real order is placed and pricing is demonstration data.</p></div>`
 }else if(state.tradeRound===1){label.textContent='ROUND 2 OF 2';const pnl=state.tradeAction==='Buy'?'−£32.10':state.tradeAction==='Short'?'+£32.10':'£0.00';c.innerHTML=`<div class="trading-body"><div class="quote-head"><div><span>MPX · 14:10</span><h2>£147.60</h2><small class="down">−3.19% since your decision</small></div><div class="position-pnl ${state.tradeAction==='Short'?'up':'down'}">${pnl}<small>YOUR P&amp;L</small></div></div>${tradingChart(true)}<div class="breaking-context"><span>NEW INFORMATION</span><b>Services inflation comes in above forecast</b><p>Investors now expect rates to stay high for longer. The index fell because future company profits are worth less when discount rates rise.</p></div><h3 class="trade-prompt">How do you manage the position?</h3><div class="resolution-options"><button data-trade-resolution="Hold and follow the original thesis"><span>HOLD</span><div><b>Keep the position</b><small>The long-term view has not changed</small></div></button><button data-trade-resolution="Close the position and cap the risk"><span>CLOSE</span><div><b>Close the position</b><small>Cap the risk and preserve flexibility</small></div></button><button data-trade-resolution="Add at the lower price"><span>ADD</span><div><b>Add 5% at the lower price</b><small>Increase exposure—and downside risk</small></div></button></div><p class="terminal-disclaimer">The next price move is deliberately unknown. Focus on process, not prediction.</p></div>`
 }else{label.textContent='SIM COMPLETE';c.innerHTML=`<div class="trade-result"><div class="trade-score"><b>${advanced?'84':'76'}</b><small>SCORE</small></div><span>SIMULATION COMPLETE</span><h2>You traded the news—not just the chart.</h2><p>You connected a market event to valuation, chose a position size and responded when the facts changed.</p><div class="trade-recap"><div><span>INITIAL ORDER</span><b>${esc(state.tradeChoices[0])}</b></div><div><span>RISK DECISION</span><b>${esc(state.tradeChoices[1])}</b></div><div><span>KEY IDEA</span><b>News changes expectations; expectations change prices.</b></div></div><div class="level-progress"><span>${state.level.toUpperCase()} TRACK</span><b>${advanced?'Advanced market context applied':'Complete more sims to unlock deeper market data'}</b></div><button class="btn primary wide" data-action="close-trading">Finish trading demo</button><p class="terminal-disclaimer">This is deliberately simpler than paper trading and is not investment advice.</p></div>`}
}
