function renderLiveMarket(){
 renderMarketWatch();const a=marketAssets[state.marketSymbol],m=a.markers[state.marketMarker]||a.markers[0];
 $('#live-market-content').innerHTML=`<div class="live-body"><div class="live-quote"><div><span>${state.marketSymbol}</span><h2 id="live-price">${a.price.toFixed(2)}</h2><small>${a.name}</small></div><div class="${a.change>=0?'up':'down'}"><b>${a.change>=0?'+':''}${a.change.toFixed(2)}%</b><small>TODAY</small></div></div><div class="market-range"><button>1D</button><button class="active">TODAY</button><button>1W</button><button>1M</button></div><div class="live-chart-shell"><div class="live-axis"><span>156</span><span>151</span><span>146</span></div><svg viewBox="0 0 360 180" preserveAspectRatio="none"><path class="market-grid" d="M0 30H360 M0 90H360 M0 150H360"/><path class="market-line" style="stroke:${a.color}" d="${a.path}"/></svg>${a.markers.map((pin,i)=>`<button class="news-pin ${i===state.marketMarker?'active':''}" style="left:${pin.x}%;top:${pin.y}%" data-news-marker="${i}"><i>${i+1}</i><span>${pin.time}</span></button>`).join('')}</div><div class="marker-detail"><div class="marker-detail-top"><span>NEWS MARKER ${state.marketMarker+1} · ${m.time}</span><b class="${m.move.startsWith('+')?'up':'down'}">${m.move}</b></div><h3>${m.title}</h3><p>${m.story}</p><div class="marker-price"><span>PRICE AT EVENT</span><b>${m.price}</b><i>→</i><button data-action="marker-story">Explore story</button></div><small class="causality-note">Why, not certainty: this is the strongest evidenced explanation. Other market forces may also have contributed.</small></div><div class="market-explainer"><span>HOW TO READ THIS</span><div><i>1</i><p><b>News lands</b><small>A verified event changes available information.</small></p></div><div><i>2</i><p><b>Expectations shift</b><small>Investors update forecasts for risk, rates or profit.</small></p></div><div><i>3</i><p><b>Price finds a new level</b><small>Buyers and sellers respond—often imperfectly.</small></p></div></div><p class="terminal-disclaimer">Simulated live data for product demonstration. Not a real-time market feed.</p></div>`;
}
