 const NewsService={
  endpoint:'/api/news',
  async getLatest(){
   // Production connection point: a backend should fetch licensed news, add AI
   // enrichment, protect API keys, and return this normalised event schema.
   if(location.protocol.startsWith('http')){
    try{
     const response=await fetch(this.endpoint,{headers:{Accept:'application/json'},signal:AbortSignal.timeout?.(1800)});
     if(response.ok){const payload=await response.json();const rows=Array.isArray(payload)?payload:payload.events;if(Array.isArray(rows)&&rows.length)return rows.map(this.normalise).filter(Boolean)}
    }catch(error){console.info('MarketPlay: /api/news unavailable; using curated primary-source fallback.')}
   }
   return fallbackEvents;
  },
  normalise(raw){
   if(!raw?.headline||!raw?.scenario)return null;
   return {...fallbackEvents[0],...raw,id:raw.id||crypto.randomUUID?.()||String(Date.now()),assets:Array.isArray(raw.assets)?raw.assets:fallbackEvents[0].assets,choices:Array.isArray(raw.choices)?raw.choices:fallbackEvents[0].choices,terms:raw.terms||{}};
  }
 };

