 let briefingActive=false,briefingUtterance=null;
 function updateBriefingButton(){const button=$('[data-action="audio-toast"]');if(!button)return;button.classList.toggle('speaking',briefingActive);button.textContent=briefingActive?'■':'▶';button.setAttribute('aria-label',briefingActive?'Stop 2 minute Market Briefing':'Play 2 minute Market Briefing')}
 function briefingScript(){
  const ordered=personalisedEvents(),userName=$('.profile-head h2')?.textContent.trim()||'there';
  const storiesText=ordered.map(({event},index)=>`${index===0?'First':`Story ${index+1}`}: ${event.headline}. ${event.whatHappened} Why it matters: ${event.why} The main market readings are ${event.assets.slice(0,2).map(asset=>`${asset.name}, ${asset.move}`).join(', ')}.`).join(' ');
  return `Welcome, ${userName}. ${storiesText} Open any story for the source, explanation and event-window market chart.`;
 }
 function playBriefing(){
  const synth=window.speechSynthesis;if(!synth||typeof SpeechSynthesisUtterance==='undefined'){toast('Voice playback is not supported in this browser');return}
  if(briefingActive){synth.cancel();briefingActive=false;updateBriefingButton();toast('Briefing stopped');return}
  synth.cancel();briefingUtterance=new SpeechSynthesisUtterance(briefingScript());briefingUtterance.lang='en-GB';briefingUtterance.rate=1.08;briefingUtterance.pitch=1;
  const voices=synth.getVoices();briefingUtterance.voice=voices.find(voice=>voice.lang==='en-GB'&&/natural|premium|enhanced|google|microsoft/i.test(voice.name))||voices.find(voice=>voice.lang==='en-GB')||voices.find(voice=>voice.lang.startsWith('en'))||null;
  briefingUtterance.onend=briefingUtterance.onerror=()=>{briefingActive=false;updateBriefingButton()};briefingActive=true;updateBriefingButton();synth.speak(briefingUtterance);toast(`Market briefing started · ${events.length} current stories`);
 }

